import{_ as t,a as s}from"./chunks/ai-diagnosis.D263A2bJ.js";import{_ as a}from"./chunks/failure-clusters.DuMKYAYD.js";import{_ as i}from"./chunks/locator-healing.BjNtRxlF.js";import{_ as o,o as n,c as r,ak as d}from"./chunks/framework.sV-XtlWr.js";const l="/diagrams/failure-clustering-semantic-merge.svg",v=JSON.parse('{"title":"AI diagnosis & failure clustering","description":"","frontmatter":{"title":"AI diagnosis & failure clustering","lang":"en-US"},"headers":[],"relativePath":"ai-diagnosis.md","filePath":"ai-diagnosis.md","lastUpdated":1788665366000}'),h={name:"ai-diagnosis.md"};function c(g,e,p,u,m,f){return n(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="ai-diagnosis-failure-clustering" tabindex="-1">AI diagnosis &amp; failure clustering <a class="header-anchor" href="#ai-diagnosis-failure-clustering" aria-label="Permalink to &quot;AI diagnosis &amp; failure clustering&quot;">​</a></h1><p>When a run finishes, Piwi groups related failures and — optionally — asks an LLM to explain them. The two features work together: clustering decides <em>what</em> to diagnose, AI diagnosis explains <em>why</em> it broke.</p><h2 id="failure-clustering" tabindex="-1">Failure clustering <a class="header-anchor" href="#failure-clustering" aria-label="Permalink to &quot;Failure clustering&quot;">​</a></h2><p>Failed test cases that share the same <strong>error fingerprint</strong> are grouped into a cluster automatically. Instead of scrolling through 20 unrelated stack traces, you see something like <em>&quot;20 failures, 3 root causes.&quot;</em></p><ul><li><strong>Fingerprinting</strong> normalizes error messages so that the same underlying failure clusters across tests, spec files, and runs. Volatile fragments are masked out: timeouts and other numbers, UUIDs and hashes, URLs and emails, and both the <em>expected</em> and <em>received</em> values of an assertion. Dynamic locator options (e.g. the <code>{ name: &#39;…&#39; }</code> of a table row) are masked too, so per-row failures collapse into one cluster — while the locator target itself (the test id / role) still distinguishes genuinely different failures.</li><li>Fingerprints are <strong>call-site agnostic</strong>: the failing stack frame is shown for context but doesn&#39;t split clusters, so one root cause reached from several spec files stays a single cluster.</li><li>The run detail page shows each failure cluster with <strong>flaky</strong> and <strong>worker-correlation</strong> heuristics, so you can tell &quot;the app is broken&quot; from &quot;worker 3 is misbehaving.&quot;</li><li>Every cluster has its own <strong>detail page</strong> with the affected tests, triage tools (status + notes), and the AI diagnosis panel.</li></ul><figure><img src="'+t+'" alt="Diagram of the fingerprint pipeline: a raw Playwright error is normalized — volatile values masked, the error category and locator extracted — hashed with SHA-256, and routed to a failure_clusters row shared across tests, spec files and runs"><figcaption>From raw error to cluster: the category, the masked message head, and the masked locator are hashed; dynamic values and the call site never split a cluster.</figcaption></figure><figure><img src="'+a+'" alt="Failure clusters tab grouping failures by normalized error signature"><figcaption>The Failure clusters tab — failures sharing an error fingerprint collapse into one row, with error type, occurrence count, and triage status.</figcaption></figure><p>Clustering is always on and requires no configuration. When the normalization algorithm is improved, existing clusters are migrated in place — re-fingerprinted from an <strong>immutable sample</strong> captured when the cluster was first created, so triage status, notes, and diagnoses survive the change. That frozen sample is deliberately separate from the sample error shown in the UI (below): the display sample can be refreshed to a better occurrence as the cluster recurs without ever moving which cluster a failure belongs to. AI diagnosis is opt-in.</p><h3 id="the-sample-error-refreshes-as-a-cluster-recurs" tabindex="-1">The sample error refreshes as a cluster recurs <a class="header-anchor" href="#the-sample-error-refreshes-as-a-cluster-recurs" aria-label="Permalink to &quot;The sample error refreshes as a cluster recurs&quot;">​</a></h3><p>A cluster is created from the first failure that matched its fingerprint, but a later occurrence often carries clearer evidence. As the same fingerprint is re-hit, Piwi refreshes the cluster&#39;s <strong>display sample error</strong> to the more useful occurrence — an error that carries a Playwright <code>Call log:</code> wins over one that doesn&#39;t, then the one with the longer message before its stack trace; equally-good occurrences leave the stored sample alone, so a recurring cluster doesn&#39;t rewrite itself every run. The signature, error type and locator shown for the cluster move with the chosen sample, and the embedding is rebuilt from it on the next post-run reconcile.</p><p>An already-generated AI <strong>title</strong> is left untouched — cheap-model titles aren&#39;t worth regenerating for a marginally better sample, and a cluster is only ever named while it is still untitled. Only the signature-derived fallback name (used when there is no title) follows the refreshed sample. The fingerprint itself never changes: it is always recomputed from the immutable creation sample, so refreshing the display can&#39;t destabilize clustering.</p><h3 id="triage-owner-and-known-issue" tabindex="-1">Triage: owner and known issue <a class="header-anchor" href="#triage-owner-and-known-issue" aria-label="Permalink to &quot;Triage: owner and known issue&quot;">​</a></h3><p>The cluster page&#39;s triage rail names an <strong>owner</strong> — who answers for these tests. It comes from a <code>piwi:owner</code> annotation on the test when one exists, otherwise from the repository&#39;s <a href="./concepts.html#tags-ownership">CODEOWNERS</a> matched against the spec&#39;s file path (the source is labeled so you can tell which). The owner links to every test that owner is responsible for, and when it is derived from CODEOWNERS a one-line hint shows how to override it per test.</p><p>The same rail pins a <strong>known issue</strong> — the Jira ticket, GitHub issue or PR that tracks the cluster. It is an entity link (<code>failure_cluster</code> type), so the provider and key are detected from the URL and unfurled; the key travels with the cluster wherever it is listed, so a triaged cluster shows what is already being done about it. Reporter or admin role is required to pin or remove one. Read the same links over MCP with <a href="./mcp.html"><code>list_links</code></a> (<code>entityType: &#39;failure_cluster&#39;</code>).</p><h3 id="semantic-merging-optional" tabindex="-1">Semantic merging (optional) <a class="header-anchor" href="#semantic-merging-optional" aria-label="Permalink to &quot;Semantic merging (optional)&quot;">​</a></h3><p>If an <strong>embedding</strong> model role is configured (Settings → AI), Piwi adds a semantic layer on top of the deterministic fingerprint. After a run, the clusters first seen in it are embedded and compared (cosine similarity) against the project&#39;s other open clusters; near-duplicates above <code>PIWI_CLUSTER_SIMILARITY_THRESHOLD</code> (default <code>0.92</code>) are merged into the longest-lived cluster. This catches failures that are the same root cause but phrased differently enough to dodge the fingerprint. Merges record a fingerprint alias so future occurrences attach to the survivor instead of re-forking. With no embedding role configured, clustering stays purely deterministic.</p><p>The text fed to the embedder is cleaned first — ANSI color codes stripped, framework stack frames collapsed, and volatile tokens (URLs, ids, received/expected values) masked — so vectors measure a failure&#39;s shape rather than its per-occurrence noise. Each pass also backfills a bounded batch of older open clusters that don&#39;t have a usable vector yet (created before the embedding role existed, or embedded with a different model), so a pre-existing backlog of near-duplicates converges over the runs that follow. Vectors are only ever compared within one embedding model: after switching models, stale vectors are re-embedded by the same backfill instead of being scored against the new model&#39;s output.</p><p>When auto-diagnose is enabled, new clusters are also given a short <strong>human-readable title</strong> (one cheap batched model call per run, using the research model when one is configured, otherwise the diagnosis model) shown in place of the raw normalized signature across the lists and the cluster page — the signature stays available on hover and below the title. Without a generated title, a cluster still gets a readable name built from what it knows — the error kind, the locator it targets, the route a navigation was heading for and the spec file it hit (<code>Timeout on getByLabel(&#39;Email address&#39;) in checkout.spec.ts</code>, <code>toHaveCount mismatch on getByRole(&#39;row&#39;) in users.spec.ts</code>, <code>Navigation timeout on /users</code>) — never the masked signature with its <code>&lt;N&gt;</code> placeholders. The signature stays as the line below the name.</p><p>Pairs that fall in the <strong>ambiguous band</strong> (similarity between <code>PIWI_CLUSTER_SUGGEST_THRESHOLD</code>, default <code>0.80</code>, and the merge threshold) aren&#39;t merged automatically. Whenever AI is configured, a model adjudicates the pair (&quot;same root cause?&quot;) — the <strong>research</strong> model when one is configured, the diagnosis model otherwise — and merges only on a high-confidence yes; when it&#39;s unsure (or no AI is configured at all), the pair becomes a <strong>merge suggestion</strong> on the project&#39;s Failure clusters tab, where a reporter or admin approves (merge) or dismisses it. The adjudicator sees more than the error text: each cluster&#39;s extracted locator, its most-affected tests, and how much the two clusters overlap (tests failing in both, runs where both fired) — signals that separate &quot;one cause, reworded message&quot; from &quot;similar boilerplate, different problems&quot;. Adjudication is budget-capped per run to control cost.</p><figure><img src="'+l+`" alt="Diagram of the semantic merging flow: new and backfilled clusters are embedded from cleaned error text, compared to open clusters by cosine similarity, and depending on the score are kept separate, adjudicated by a model that can merge or file a suggestion, or auto-merged with a fingerprint alias recorded"><figcaption>The semantic layer: freshly embedded clusters seek their nearest neighbour; the cosine score decides between keeping them apart, asking a model (or a human), and merging outright. Thresholds are the <code>PIWI_CLUSTER_SUGGEST_THRESHOLD</code> and <code>PIWI_CLUSTER_SIMILARITY_THRESHOLD</code> defaults.</figcaption></figure><p>Embedding-based reconciliation runs after every finished run whenever an embedding role is configured — it is independent of the auto-diagnose toggle.</p><h2 id="did-the-fix-work" tabindex="-1">Did the fix work? <a class="header-anchor" href="#did-the-fix-work" aria-label="Permalink to &quot;Did the fix work?&quot;">​</a></h2><p>A cluster used to go quiet and stay open forever — nothing ever confirmed it was actually fixed. Now every run answers that.</p><p>When a run executes every test a cluster covers and they all pass, Piwi records the fix: the run, the commit, and how long the cluster was open. Three verdicts, because they are not the same claim:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Means</th></tr></thead><tbody><tr><td><strong>Stopped failing</strong></td><td>The tests pass again. A flaky test can achieve this by accident.</td></tr><tr><td><strong>Diagnosis verified</strong></td><td>The commits since the last failing run touched a file the <a href="#what-a-diagnosis-contains">suggested patch</a> named — the change Piwi pointed at is the change that fixed it.</td></tr><tr><td><strong>Regressed</strong></td><td>A fix was recorded, and the cluster is failing again. A fix that didn&#39;t hold is worth knowing about.</td></tr></tbody></table><p>The verdict appears on the cluster page, under the signature, with the run the fix landed in, the commit, and how long the cluster stayed open. The project&#39;s <strong>Failure clusters</strong> tab shows it beside the triage status — deliberately as a second badge rather than folded into the first, because the two answer different questions: the status is what a person declared, the verdict is what the runs showed. A cluster somebody marked <em>resolved</em> that is quietly failing again shows both, and that disagreement is the point.</p><p>Two rules keep the verdict honest:</p><ul><li><strong>Every affected test must pass</strong>, not just some — a cluster is one root cause, and half of it passing means it isn&#39;t fixed. A test that didn&#39;t execute hasn&#39;t been shown to pass, so it counts against the cluster just as a failure would.</li><li><strong>A filtered run can close a cluster</strong> as long as it covered the whole cluster. Re-running exactly the affected tests with <code>--grep</code> and seeing them all pass is enough; a run that skipped even one of them is not, whether it was filtered or a full run that happened to miss it.</li></ul><p>The verdict moves the triage status only when the evidence is strong enough to stand in for a person: <em>Diagnosis verified</em> sets an <strong>open</strong> cluster to <strong>resolved</strong>, and <em>Regressed</em> sets a <strong>resolved</strong> cluster back to <strong>open</strong>. Each transition appends a line to the triage note (&quot;Resolved automatically: diagnosis verified in run #42&quot;, &quot;Reopened automatically: regressed in run #57&quot;), so the status still reads as something you can audit and override. <em>Stopped failing</em> alone changes nothing — a flaky test achieves it by accident — and a cluster marked <em>ignored</em> is never touched. The verdict badge stays separate from the status either way.</p><p>Two <a href="./notifications.html">notifications</a> follow the verdict: <code>cluster.fixed</code> whenever a fix is recorded (its payload says which verdict), and <code>cluster.regressed</code> when a fix does not hold.</p><p>When <a href="./ci.html#pull-request-feedback">pull-request feedback</a> is on, the comment gains a <strong>Fixed by this change</strong> section naming what the pull request closed. That section is worth a comment on its own, so a green run that closed a cluster still gets one even with <em>only comment on failures</em> set.</p><h2 id="enabling-ai-diagnosis" tabindex="-1">Enabling AI diagnosis <a class="header-anchor" href="#enabling-ai-diagnosis" aria-label="Permalink to &quot;Enabling AI diagnosis&quot;">​</a></h2><p>Configure a provider via <strong>Settings → AI</strong>, or with environment variables (env always takes precedence over values stored through the UI, and the UI shows env-managed fields read-only).</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PIWI_AI_PROVIDER</code></td><td><code>anthropic</code> or <code>openai</code></td></tr><tr><td><code>PIWI_AI_API_KEY</code></td><td>Provider API key (stored encrypted when set via the UI; never returned by the API)</td></tr><tr><td><code>PIWI_AI_MODEL</code></td><td>Model name (default: <code>claude-opus-4-8</code> for Anthropic)</td></tr><tr><td><code>PIWI_AI_BASE_URL</code></td><td>Base URL for OpenAI-compatible providers (e.g. Ollama, LM Studio, vLLM)</td></tr><tr><td><code>PIWI_AI_AUTO_DIAGNOSE</code></td><td><code>true</code> to automatically diagnose new clusters when a run finishes</td></tr><tr><td><code>PIWI_AI_AUTO_DIAGNOSE_MAX</code></td><td>Max clusters auto-diagnosed per finished run (budget cap; default <code>3</code>)</td></tr><tr><td><code>PIWI_AI_RESEARCH_MODEL</code> / <code>_PROVIDER</code> / <code>_BASE_URL</code> / <code>_API_KEY</code></td><td>Optional <strong>research</strong> model for two-stage diagnosis; provider/base URL/key default to the main ones</td></tr><tr><td><code>PIWI_AI_EMBEDDING_PROVIDER</code> / <code>_MODEL</code> / <code>_BASE_URL</code> / <code>_API_KEY</code></td><td>Optional <strong>embedding</strong> model for semantic failure clustering (OpenAI-compatible only — Anthropic has no embeddings API)</td></tr></tbody></table><p>When a run finishes and <code>PIWI_AI_AUTO_DIAGNOSE</code> is on, the <code>PIWI_AI_AUTO_DIAGNOSE_MAX</code> budget is spent where it buys the most. The run&#39;s clusters are ordered by their representative failing execution&#39;s top <a href="./evidence.html#clues">clue</a>: a cluster whose failure carries <strong>no deterministic clue</strong> — the one the model has to reason about from scratch — goes first, then the ones with only a weak clue, and only then a failure a strong clue already explains, with the newest cluster breaking ties. So the budget lands on the failures that most need a model, not simply the three newest.</p><p><code>GET /api/ai/status</code> reports whether AI is configured (without ever exposing the key); the UI uses it to show or hide AI actions.</p><h3 id="streaming-diagnosis" tabindex="-1">Streaming diagnosis <a class="header-anchor" href="#streaming-diagnosis" aria-label="Permalink to &quot;Streaming diagnosis&quot;">​</a></h3><p>Instead of waiting for a synchronous response, the diagnosis can be <strong>streamed</strong> via SSE (Server-Sent Events) — the model&#39;s reasoning tokens appear in the UI as they arrive:</p><ul><li><strong><code>POST /api/failure-clusters/[id]/diagnose/stream</code></strong> — same request body as the synchronous endpoint, but the response is a <code>text/event-stream</code> with <code>event: thinking</code> chunks containing incremental text, then a final <code>event: result</code> with the complete diagnosis.</li><li>The client uses <code>fetch()</code> with <code>POST</code> (not <code>EventSource</code>) so it can send request body params (additional context, images, base commit, etc.). The response body is read as a <code>ReadableStream</code> and parsed for SSE messages.</li><li>See the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> for the exact protocol (the in-app API reference at <code>/docs</code> shows the same spec).</li><li>In the UI, the live thinking panel shows the accumulating text with a stage indicator and auto-scroll. When the stream completes, the panel transitions to the full result card.</li></ul><p>To be told when a diagnosis finishes without watching the panel, turn on <strong>Settings → AI → Diagnosis notifications</strong> — a per-browser preference (stored on that device only) that shows a browser notification on completion once you grant the permission.</p><h3 id="model-roles" tabindex="-1">Model roles <a class="header-anchor" href="#model-roles" aria-label="Permalink to &quot;Model roles&quot;">​</a></h3><p>Piwi calls models in up to three distinct roles, each with its own complete provider configuration (or a <strong>reuse</strong> pointer to inherit another role&#39;s provider and credentials):</p><ul><li><strong>Diagnosis</strong> — the main model that writes the final diagnosis (required to enable AI).</li><li><strong>Research</strong> — an optional cheaper/faster model that pre-analyzes the failure first (<em>two-stage diagnosis</em>).</li><li><strong>Embedding</strong> — an optional embeddings model that powers semantic failure clustering.</li></ul><p>Configure each role in <strong>Settings → AI → Model providers</strong>. A role set to <em>reuse</em> another role uses that role&#39;s provider, key, and base URL — only its model can differ — so you don&#39;t re-enter credentials for, say, a Haiku research pass on the same Anthropic key.</p><h3 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h3><p><strong>Anthropic (recommended)</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-4-8</span></span></code></pre></div><p><strong>OpenAI</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gpt-4o</span></span></code></pre></div><p><strong>OpenAI-compatible / local (Ollama, etc.)</strong> — set <code>provider</code> to <code>openai</code> and point <code>base URL</code> at the local endpoint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_PROVIDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:11434/v1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">llama3.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ollama</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # any non-empty value for local servers</span></span></code></pre></div><p>Use <strong>Settings → AI → Test</strong> to smoke-test the configured provider.</p><h2 id="what-a-diagnosis-contains" tabindex="-1">What a diagnosis contains <a class="header-anchor" href="#what-a-diagnosis-contains" aria-label="Permalink to &quot;What a diagnosis contains&quot;">​</a></h2><p>A diagnosis is grounded in your actual run — it is not a generic &quot;ask AI&quot; button. Each result includes:</p><ul><li><strong>Category</strong> and <strong>confidence</strong></li><li><strong>Root cause</strong> — the most likely explanation</li><li><strong>Evidence</strong> — the signals the model relied on</li><li><strong>Suggested fix</strong> and <strong>prevention tips</strong></li></ul><figure><img src="`+s+'" alt="The AI diagnosis card at the foot of a failure cluster page"><figcaption>The AI diagnosis at the foot of a cluster page — category, confidence, root cause, the evidence it relied on, and a suggested fix — grounded in the same error and evidence the page shows above it.</figcaption></figure><h2 id="diagnosing-one-execution" tabindex="-1">Diagnosing one execution <a class="header-anchor" href="#diagnosing-one-execution" aria-label="Permalink to &quot;Diagnosing one execution&quot;">​</a></h2><p>The <a href="./ui-overview.html#failure-cluster-detail">failure cluster</a> page diagnoses a <em>group</em> of failures that share a fingerprint. When you are looking at a single failing execution, the <a href="./evidence.html#one-execution-diagnosis-first">test case detail</a> page&#39;s Fix card has a <strong>Diagnosis</strong> section that diagnoses <em>just that execution</em> — the same panel the cluster page uses, on the same model and structured result, scoped to the one run in front of you. This is handy when a failure hasn&#39;t clustered yet, or when you want a diagnosis grounded in this specific execution&#39;s evidence rather than the cluster aggregate.</p><p>A stored diagnosis stays on screen <strong>whether or not a provider is configured</strong> — removing the key never hides a result you already have. With no provider the section shows one line, <em>AI is not configured · Configure · Copy prompt</em>, where <strong>Copy prompt</strong> copies the exact request the model would receive (error, steps, console, network, ARIA snapshot, source — plus, when a trace was uploaded, the full call stack with embedded source and the trace&#39;s complete network activity — all trimmed to the <a href="#context-limits-and-token-cost">context limits</a>) so you can paste it into your own AI tool.</p><p>With a provider configured, <strong>Diagnose with AI</strong> runs the diagnosis inline and renders the result (category, confidence, root cause, evidence, suggested fix) right in the section; cited evidence links jump to the matching section on the page, and a <strong>coverage strip</strong> maps which evidence sections are present, truncated or absent. The result is stored per execution, so it survives a reload, and you can add free-text context or re-diagnose. Execution-scoped and cluster-scoped diagnoses are independent — running one never overwrites the other.</p><h2 id="scm-grounded-context" tabindex="-1">SCM-grounded context <a class="header-anchor" href="#scm-grounded-context" aria-label="Permalink to &quot;SCM-grounded context&quot;">​</a></h2><p>The real power is feeding the model the code that changed. On a cluster page you can:</p><ul><li><strong>Pin a baseline commit</strong> — the diagnosis includes the aggregate diff between that commit and the run, so the model sees what changed.</li><li><strong>Browse and cherry-pick commits</strong> — add the full diff of specific commits to the context for targeted analysis.</li><li><strong>Preview the exact context</strong> that will be sent before running (<code>GET /api/failure-clusters/[id]/context</code>), so there are no surprises about what leaves your server.</li></ul><h3 id="commit-selection-algorithm" tabindex="-1">Commit selection algorithm <a class="header-anchor" href="#commit-selection-algorithm" aria-label="Permalink to &quot;Commit selection algorithm&quot;">​</a></h3><p>When you trigger a diagnosis, Piwi determines the commit range to diff using the following priority chain:</p><ol><li><p><strong>Manual override</strong> — if you pinned a baseline commit (or the cluster has a <code>manualBaseCommit</code> saved), that commit is used as <code>fromSha</code>. This applies even in auto-diagnose and MCP-triggered diagnoses. The <code>Data Coverage</code> block in the AI context will show <code>baselineKind: manual</code>.</p></li><li><p><strong>Project-wide last-green run</strong> — Piwi looks for the most recent test run (for the same project) that finished with <code>status = &#39;passed&#39;</code> <em>before</em> the <strong>first</strong> run in which this cluster appeared (<code>firstSeenRunId</code>, not <code>lastSeenRunId</code>). Using <code>firstSeenRunId</code> gives the tightest possible causal window: the diff covers exactly the commits introduced between when the suite was last fully-green and when the failure was first observed. <code>baselineKind: run-green</code>.</p></li><li><p><strong>Per-test last-passing fallback</strong> — if no project-wide green run exists (e.g. the project is new, or CI has been failing for a long time), Piwi falls back to the last run where <em>this specific test case</em> passed. This is less precise than a project-green baseline but still vastly better than no diff. <code>baselineKind: test-green</code>.</p></li><li><p><strong>No SCM data</strong> — if none of the above yields both a baseline commit and a current commit (from the run&#39;s SCM metadata), no diff is fetched. The <code>Data Coverage</code> block marks <code>scmInvestigation</code> absent and explains why (missing repository URL, no SCM token, or a fetch error).</p></li></ol><p>The <code>coverage.scm.baselineKind</code> field is available on every diagnosis response and in the context-preview endpoint, so you can always tell which path was taken. If an SCM fetch fails, <code>coverage.scm.error</code> contains the first 300 characters of the error message.</p><h4 id="relevance-scoring" tabindex="-1">Relevance scoring <a class="header-anchor" href="#relevance-scoring" aria-label="Permalink to &quot;Relevance scoring&quot;">​</a></h4><p>Changed files are ranked by relevance to the failing test before patch text is included in the context (the patch budget is limited). The scoring signals are:</p><table tabindex="0"><thead><tr><th>Signal</th><th style="text-align:right;">Score</th></tr></thead><tbody><tr><td>Patch removes a line containing a string the test was trying to locate (smoking gun)</td><td style="text-align:right;">+8</td></tr><tr><td>Patch touches (but doesn&#39;t remove) a locator-literal string</td><td style="text-align:right;">+6</td></tr><tr><td>Test imports this file (basename match)</td><td style="text-align:right;">+5</td></tr><tr><td>Changed file IS the test file</td><td style="text-align:right;">+4</td></tr><tr><td>Changed file shares the test file&#39;s basename</td><td style="text-align:right;">+2</td></tr><tr><td>Filename token overlaps with the test title or page ARIA state</td><td style="text-align:right;">+1 each</td></tr><tr><td>File is under a source directory (<code>src/</code>, <code>lib/</code>, <code>app/</code>, …)</td><td style="text-align:right;">+1</td></tr><tr><td>File is a lockfile, doc, or config</td><td style="text-align:right;">−1</td></tr></tbody></table><p>Files scoring ≤ 2 are excluded from the &quot;Top Suspected Change&quot; callout (a low-signal hint is worse than none), but they still appear in the full changed-files list.</p><h3 id="full-source-files" tabindex="-1">Full source files <a class="header-anchor" href="#full-source-files" aria-label="Permalink to &quot;Full source files&quot;">​</a></h3><p>A diff shows only the lines that changed. To write a patch the model needs the surrounding code too, so — when SCM is reachable — Piwi also fetches the <strong>full current content</strong> of the most-suspect changed files (top-ranked by the relevance score above) and the failing test&#39;s local imports (page objects, helpers, fixtures resolved one hop from the test&#39;s <code>import</code> statements), at the commit under test. These land in a <code>Source Files</code> context section with <code>NNNN | </code> line numbers so the model can compute correct hunk headers.</p><p>Capped by <code>PIWI_AI_MAX_SOURCE_FILES</code> (default 4, set to 0 to disable) and <code>PIWI_AI_MAX_SOURCE_FILE_CHARS</code> (default 12000). Fetched over the same SCM provider API as the diff (GitHub/GitLab/Bitbucket), cached per commit SHA. The <code>coverage.sourceFiles</code> field on the context/diagnosis response lists which files were pulled in.</p><h3 id="validated-patches" tabindex="-1">Validated patches <a class="header-anchor" href="#validated-patches" aria-label="Permalink to &quot;Validated patches&quot;">​</a></h3><p>Every <code>suggestedFix.patch</code> is checked server-side, before it reaches you, against the exact source files the model was shown: Piwi parses the unified diff and dry-runs each hunk against the real file content (tolerating line-offset drift). The result is stored on the diagnosis as <code>details.patchValidation.status</code> and shown as a badge on the patch:</p><table tabindex="0"><thead><tr><th>Status</th><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td><code>applies</code></td><td>✅ Applies cleanly</td><td>Every hunk matched at its stated position</td></tr><tr><td><code>applies-with-offset</code></td><td>⚠️ Applies with offset</td><td>Matched, but at a shifted line — <code>git apply</code> should still succeed</td></tr><tr><td><code>stale-file</code></td><td>❌ Does not apply</td><td>The file diverged from what the patch expects</td></tr><tr><td><code>invalid</code></td><td>❌ Invalid diff</td><td>The text isn&#39;t a parseable unified diff</td></tr><tr><td><code>unchecked</code></td><td>Unverified</td><td>The target file wasn&#39;t in context, so the patch couldn&#39;t be validated</td></tr></tbody></table><p>A wrong patch is worse than none, so the model is instructed to set <code>patch</code> to null unless it can quote the lines it changes from the <code>Source Files</code> / <code>Test Source</code> sections. The patch card offers <strong>Copy</strong>, <strong>Copy <code>git apply</code> command</strong>, and <strong>Download <code>.patch</code></strong>; applying an AI-suggested patch is always manual — the dashboard never writes one to your repository. The one feature that does write to your repository is <a href="./auto-heal.html">auto-heal</a>: deterministic one-line locator edits taken from captured snapshots, never model output, and off by default.</p><h2 id="locator-healing" tabindex="-1">Locator healing <a class="header-anchor" href="#locator-healing" aria-label="Permalink to &quot;Locator healing&quot;">​</a></h2><p>When the failure is a broken locator, the context includes an <strong>Alternative Locators</strong> section: ranked replacement locators sourced from a prior passing run (highest confidence — captured against the real DOM), from a fresh match of the renamed/moved element on the failing page, or from the failure-time ARIA snapshot. The section also names a single <strong>recommended fix</strong> — convention-preserving where the original locator style is stable enough — which the model is instructed to use verbatim in <code>suggestedFix.code</code> rather than fabricating a locator. When nothing scores as stable, it advises adding a <code>data-testid</code> to the application as the durable fix. When the locator resolved and the failure came after it (an assertion mismatch, a disabled element), the section instead states that healing is not applicable, so the model does not propose a replacement locator for a problem that is not one.</p><figure><img src="'+i+`" alt="Locator fix panel with ranked replacement locators and a recommended fix"><figcaption>The Locator fix panel — the broken locator, ranked replacements scored for stability, and a single recommended fix that preserves your locator style.</figcaption></figure><p>This evidence is generated from the locator snapshots recorded by the <a href="./capture-fixtures.html">capture fixtures</a> while tests run — make sure your specs import <code>test</code> from a fixtures file that extends <code>piwiFixtures</code>. Capture is gated by the default-on <code>captureLocators</code> reporter option. The same data drives the standalone <strong>Locator fix</strong> panel on the <a href="./evidence.html#one-execution-diagnosis-first">execution</a> and cluster pages.</p><h2 id="fix-plans" tabindex="-1">Fix plans <a class="header-anchor" href="#fix-plans" aria-label="Permalink to &quot;Fix plans&quot;">​</a></h2><p>Everything above is assembled into one answer — the diagnosis and its validated patch, the ranked locator replacement with the exact file and line to edit, the failing tests, the owning team, and the command that verifies the work. The same plan is reachable three ways:</p><ul><li><strong>On the cluster page</strong> — the cluster&#39;s single <strong>Fix</strong> card gathers the diagnosis and its patch (copy, <code>git apply</code>, download), the recommended locator fix, the verify command, and a <strong>Copy as Markdown</strong> action that hands you the whole plan for a ticket. <strong>Re-run in CI</strong> is the page&#39;s header action when that is configured. The failing tests are the page&#39;s <strong>Affected tests</strong> list and the owner is on the header&#39;s facts line, so the plan is assembled from the page you are already reading rather than duplicated in a card of its own.</li><li><strong>As Markdown</strong> — <code>GET /api/failure-clusters/:id/fix-plan?format=markdown</code> returns the same rendering as plain text, so an export or a script can drop it straight into an issue.</li><li><strong>For agents</strong> — the <code>get_fix_plan</code> <a href="./mcp.html">MCP tool</a> returns the structured plan, so a coding agent gets in one call what a person reads on the card.</li></ul><p>The last part is what makes it a loop rather than a lookup. The plan states which Playwright command runs exactly the affected tests, and that Piwi will record the fix once they pass — so an agent (or a person) can confirm the work instead of leaving someone to decide whether it landed.</p><p>Every section degrades on its own. A cluster with no AI diagnosis still returns its failing tests, its locator suggestions and its verification command, so the plan is useful without an AI provider configured at all.</p><p>Worth stating plainly: none of this leaves your machine. The dashboard is yours, the model is whichever one you configured (including a local one), and the patch was validated against your own source before you saw it.</p><h3 id="reproduce-and-bisect" tabindex="-1">Reproduce and bisect <a class="header-anchor" href="#reproduce-and-bisect" aria-label="Permalink to &quot;Reproduce and bisect&quot;">​</a></h3><p>The fix plan also hands back the two things you do next: a copy-paste recipe that reproduces the failure locally, and a generated <code>git bisect</code> that finds the commit that broke it. Both sit in a <strong>Reproduce</strong> section on the Fix card — on the cluster page and on the failing execution&#39;s page — and travel with the plan through <code>?format=markdown</code> and the <code>get_fix_plan</code> MCP tool.</p><p>The <strong>recipe</strong> is the local reproduction, in order: check out the commit the run failed on (<code>git switch --detach &lt;sha&gt;</code>), install dependencies, pin Playwright to the version the run used, install the browser it ran on, and run exactly the failing test. Each part degrades on its own — no recorded commit skips the checkout and says so, an unknown Playwright version drops the pin — and the run&#39;s environment (label, base URL) is listed beside it. Every command is <code>git</code>, <code>npm</code> or <code>npx</code>, so it is identical on Linux, macOS and Windows; the dashboard still offers a <strong>Linux / macOS</strong> and a <strong>Windows (PowerShell)</strong> tab so a reader copies the form they expect.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check out the failing commit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9a8b7c6d5e4f30211203f4e5d6c7b8a99a8b7c6d</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pin Playwright to the run&#39;s version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @playwright/test@1.52.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the failing test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tests/admin/users.spec.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Chromium&quot;</span></span></code></pre></div><p>The <strong>bisect</strong> walks the commits between the last green run and the failing one, re-running the test at each step — a non-zero exit marks a commit bad — until it names the first commit that broke it, then <code>git bisect reset</code> returns you to where you started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">failing-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">last-green-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tests/admin/users.spec.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Users table paginates 25 rows per page&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bisect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span></span></code></pre></div><p>The bisect needs a <strong>last-green commit</strong> and an <strong>SCM connection</strong>: when Piwi has no commit for the failing run or for the last green run before it, or the two are the same commit, the section says so in one line instead of showing a script. The recipe is always there.</p><p>In the <a href="/desktop.html#reproducing-a-failure-and-finding-the-breaking-commit">desktop app</a> the same section can also do the work for you: <strong>Reproduce here</strong> runs the recipe against the linked folder in a throwaway <code>git worktree</code> — your checkout is never touched — and <strong>Find the breaking commit here</strong> drives the whole bisect step by step, with live progress and a stop that stops, then records the first bad commit on the cluster so it shows here and in the fix plan afterwards.</p><h3 id="fixed-before" tabindex="-1">Fixed before <a class="header-anchor" href="#fixed-before" aria-label="Permalink to &quot;Fixed before&quot;">​</a></h3><p>An open cluster often is not new — the same failure, or one close to it, was fixed weeks ago. The fix plan looks back over the project&#39;s <strong>resolved</strong> clusters (resolved, or with a verified fix that held) and, when one resembles the open cluster closely enough, shows it in a <strong>Fixed before</strong> section on the Fix card — on the cluster page and on the failing execution&#39;s page, and in the <code>?format=markdown</code> export and the <code>get_fix_plan</code> MCP tool.</p><p>A match is scored deterministically first — the same fingerprint family (error kind, masked message, masked locator), the same failing locator, the same spec file or test — and then, when an <a href="#model-roles">embedding model</a> is configured, by semantic similarity of the stored cluster vectors. The top three matches are shown, each with <strong>when</strong> it was resolved, the <strong>commit</strong> that fixed it (linked when the repository host is known), <strong>how long</strong> it stayed open, the triage note, the owner, the earlier diagnosis and its thumbs feedback, and one short reason it matched (&quot;same error and locator&quot;, &quot;same spec, similar message (0.91)&quot;). Nothing matches → the section renders nothing, no empty-state noise.</p><p><strong>Apply the same triage</strong> copies the earlier cluster&#39;s triage note onto the open one, prefixed <code>Same as cluster #N:</code> so the history reads as an intentional reuse. It never changes the open cluster&#39;s status — a new cluster is never marked resolved just because an old one was. The same top match is fed to the AI diagnosis as a <em>Previously fixed similar failure</em> clue, so the model can reuse a known fix rather than re-derive it.</p><h2 id="diagnosis-history" tabindex="-1">Diagnosis history <a class="header-anchor" href="#diagnosis-history" aria-label="Permalink to &quot;Diagnosis history&quot;">​</a></h2><p>Every re-diagnose snapshots the previous result before overwriting it, so a cluster keeps up to 50 prior versions. The <strong>History</strong> control in the diagnosis panel header opens a slide-over listing every version newest-first — when it ran, the model, category, confidence, feedback and token cost — with the current diagnosis on top. Selecting one renders it read-only, with a one-line summary of what changed since it (category, confidence, root cause, patch status). It is how you see whether a re-run actually moved the verdict, and why.</p><h3 id="when-a-diagnosis-is-stale" tabindex="-1">When a diagnosis is stale <a class="header-anchor" href="#when-a-diagnosis-is-stale" aria-label="Permalink to &quot;When a diagnosis is stale&quot;">​</a></h3><p>A completed diagnosis is flagged <strong>may be stale</strong> only when the failure has genuinely moved on: the hash of the current evidence differs from the hash stored when the diagnosis ran <strong>and</strong> the cluster is still failing. A cluster whose fix is verified, or one that has stopped failing or been triaged as resolved, never shows the banner — the diagnosis describes a failure that is no longer happening. When Piwi can tell why the evidence changed, the banner says so: new occurrences since the diagnosis, versus a change in the evidence itself.</p><h2 id="custom-instructions" tabindex="-1">Custom instructions <a class="header-anchor" href="#custom-instructions" aria-label="Permalink to &quot;Custom instructions&quot;">​</a></h2><p>Tailor the analysis to your stack with <strong>global</strong> instructions (Settings → AI) and <strong>per-project</strong> instructions. Use them to describe your architecture, common false positives, or house style for fixes.</p><h2 id="context-limits-and-token-cost" tabindex="-1">Context limits (and token cost) <a class="header-anchor" href="#context-limits-and-token-cost" aria-label="Permalink to &quot;Context limits (and token cost)&quot;">​</a></h2><p>Every piece of evidence sent to the model costs tokens. Piwi caps each input so diagnoses stay fast and affordable. Defaults live in <code>shared/ai-context-limits.ts</code>; override them in <strong>Settings → AI</strong> or via env (env wins; the UI then shows the field read-only).</p><p>The full list of <code>PIWI_AI_MAX_*</code> limit variables, their defaults and their clamping ranges lives in the <a href="./configuration.html#ai-context-limits">Configuration reference → AI context limits</a> — generated from the same registry the server reads, so it can never drift from the code.</p><p>Screenshots are the one input a provider can refuse outright: many self-hosted and gateway models are text-only and reject a request that carries images. Piwi retries that call without them, so the diagnosis still runs on the text evidence. Setting <code>PIWI_AI_MAX_IMAGES=0</code> skips the rejected first attempt.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs entirely in your browser with no AI provider — yet the diagnosis experience is fully wired. Several failing clusters ship with a completed diagnosis (category, confidence, evidence with citations, a validated suggested patch, per-stage pipeline stats, and auto-selected suspect commits); others are left undiagnosed so you can trigger a <strong>simulated streaming diagnosis</strong> yourself and watch the reasoning tokens arrive. The diagnoses are generated from each cluster&#39;s real seeded evidence (occurrences, failure rate, affected tests, browsers) and a canned SCM history, so the <strong>Context sent to AI</strong> modal, the data-coverage map, the commit browser, baseline pinning, and the diagnosis version history all behave as they do against a real server. Suggested-fix patches are validated against the seeded source files, so the &quot;Applies cleanly&quot; badge means the same thing it does in production.</p><p>The demo also carries three clusters with a recorded resolution, one per verdict — including one marked <em>resolved</em> by a person that the runs show failing again, so the difference between what somebody declared and what actually happened is visible without waiting for it to occur.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>API keys are encrypted at rest with <a href="./configuration.html#general"><code>PIWI_SECRET_KEY</code></a>. When you run a diagnosis, the bounded context above is sent to your configured provider — so for fully local analysis, use Ollama or another self-hosted OpenAI-compatible model and keep everything on your own infrastructure.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./concepts.html#error-fingerprint-failure-cluster">Core concepts</a> — fingerprints, clusters, and baselines in one place</li><li><a href="./privacy.html">Privacy &amp; data flow</a> — exactly what a diagnosis sends, and where</li><li><a href="./configuration.html">Configuration reference</a> — all environment variables</li><li><a href="./notifications.html">Notifications</a> — subscribe to <code>cluster.new</code>, <code>cluster.fixed</code>, <code>cluster.regressed</code> and <code>diagnosis.completed</code> to get alerted when a new cluster appears, a fix lands or regresses, or a diagnosis completes (browser, email, Slack, or webhook)</li><li><a href="./mcp.html">MCP server</a> — let AI agents query clusters and diagnoses directly</li></ul>`,117)])])}const x=o(h,[["render",c]]);export{v as __pageData,x as default};
